from ortools.sat.python import cp_model
import json

def solve_flow_shop_scheduling():
    units = [
        "Alpha-001", "Beta-002", "Gamma-003", "Delta-004", "Epsilon-005",
        "Zeta-006", "Eta-007", "Theta-008", "Iota-009", "Kappa-010",
        "Lambda-011", "Mu-012", "Nu-013", "Xi-014", "Omicron-015"
    ]

    stations = [1, 2, 3, 4, 5]

    processing_times = {
        "Alpha-001": [80, 59, 59, 31, 30],
        "Beta-002": [13, 83, 70, 64, 88],
        "Gamma-003": [64, 85, 76, 11, 14],
        "Delta-004": [77, 85, 10, 9, 22],
        "Epsilon-005": [17, 70, 65, 32, 93],
        "Zeta-006": [78, 35, 19, 58, 48],
        "Eta-007": [82, 2, 77, 98, 10],
        "Theta-008": [4, 76, 86, 95, 7],
        "Iota-009": [72, 46, 21, 25, 14],
        "Kappa-010": [93, 72, 75, 4, 91],
        "Lambda-011": [68, 69, 96, 45, 5],
        "Mu-012": [25, 46, 3, 60, 43],
        "Nu-013": [67, 3, 50, 87, 30],
        "Xi-014": [80, 57, 57, 31, 79],
        "Omicron-015": [43, 71, 66, 1, 39]
    }

    model = cp_model.CpModel()

    S = {}
    horizon = sum(sum(processing_times[i]) for i in units)
    for i in units:
        for k in stations:
            S[(i, k)] = model.NewIntVar(0, horizon, f"S_{i}_{k}")

    Cmax = model.NewIntVar(0, horizon, "Cmax")

    intervals = {}
    for i in units:
        for k in stations:
            duration = processing_times[i][k-1]
            end_var = model.NewIntVar(0, horizon, f"end_{i}_{k}")
            model.Add(end_var == S[(i, k)] + duration)
            interval_var = model.NewIntervalVar(
                S[(i, k)], duration, end_var, f"interval_{i}_{k}"
            )
            intervals[(i, k)] = interval_var

    for i in units:
        for k in range(1, 5):
            model.Add(S[(i, k+1)] >= S[(i, k)] + processing_times[i][k-1])

    for k in stations:
        station_intervals = [intervals[(i, k)] for i in units]
        model.AddNoOverlap(station_intervals)

    for i in units:
        model.Add(Cmax >= S[(i, 5)] + processing_times[i][4])

    model.Minimize(Cmax)

    solver = cp_model.CpSolver()
    solver.parameters.max_time_in_seconds = 30.0
    solver.parameters.num_search_workers = 8

    status = solver.Solve(model)

    if status in (cp_model.OPTIMAL, cp_model.FEASIBLE):
        total_service_time = solver.Value(Cmax)

        first_station_times = [(i, solver.Value(S[(i, 1)])) for i in units]
        first_station_times.sort(key=lambda x: x[1])
        sequence_names = [unit for unit, _ in first_station_times]

        unit_to_index = {name: idx + 1 for idx, name in enumerate(units)}
        unit_sequence = [unit_to_index[name] for name in sequence_names]

        print(json.dumps({
            "unit_sequence": unit_sequence,
            "total_service_time": total_service_time
        }))
    else:
        print(json.dumps({
            "unit_sequence": [],
            "total_service_time": -1
        }))

if __name__ == "__main__":
    solve_flow_shop_scheduling()
